import{_ as l,D as a,o as c,c as p,m as t,a as r,G as o,S as d}from"./chunks/framework.DuIEtbrD.js";const f=JSON.parse('{"title":"ReactNative调试技巧","description":"掌握React Native调试核心技巧：Chrome DevTools断点追踪、React DevTools组件分析、性能优化策略、跨平台问题定位方法，助你快速排查应用崩溃、样式异常与逻辑错误，提升开发效率！","frontmatter":{"title":"ReactNative调试技巧","description":"掌握React Native调试核心技巧：Chrome DevTools断点追踪、React DevTools组件分析、性能优化策略、跨平台问题定位方法，助你快速排查应用崩溃、样式异常与逻辑错误，提升开发效率！","keywords":"ReactNative,RN,调试,ChromeDevTools,Flipper,ios,android,hermes","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/react-logo.png"},"headers":[],"relativePath":"frontend/react-native/debugger.md","filePath":"frontend/react-native/debugger.md","lastUpdated":1776945570000}'),h={name:"frontend/react-native/debugger.md"};function g(u,e,m,b,v,D){const s=a("Obsolete"),n=a("Reward"),i=a("Gitalk");return c(),p("div",null,[e[0]||(e[0]=t("h1",{id:"reactnative调试技巧",tabindex:"-1"},[r("ReactNative调试技巧 "),t("a",{class:"header-anchor",href:"#reactnative调试技巧","aria-label":'Permalink to "ReactNative调试技巧"'},"​")],-1)),o(s,{date:"2024-01-01"}),e[1]||(e[1]=d(`<p>你是否知道，React Native开发者平均把37.6%的工作时间献给了调试黑箱？当热重载突然失效、红屏警告像午夜凶铃般闪现、安卓iOS双平台BUG像打地鼠般此起彼伏时，我们是否正在用21世纪的工具进行石器时代的debug</p><p>别急着给<code>node_modules</code>办葬礼，当<code>console.log</code>大军压境时，你需要的不是更多的日志，本文以ReactNative开发框架Expo为基础展开，介绍一套让React Native调试从玄学变科学的组合拳——从Hermes引擎的火焰图到DevTool的调试技巧，让我们开启这场让BUG无处遁形的技术狩猎</p><h2 id="基本调试" tabindex="-1">基本调试 <a class="header-anchor" href="#基本调试" aria-label="Permalink to &quot;基本调试&quot;">​</a></h2><p>React Native提供了一个应用内开发者菜单，提供调试功能。你可以通过摇动设备或通过键盘快捷键进入开发菜单</p><ul><li>iOS模拟器: <code>Ctrl + Cmd ⌘ + Z (or Device &gt; Shake)</code></li><li>Android模拟器：<code>Cmd ⌘ + M (macOS) or Ctrl + M (Windows and Linux)</code></li></ul><p>在不同平台的模拟器上通过以上的快捷键打开内部的调试面板</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/debugging-dev-menu-076-f2f50e00c40ec72dede2d760c174b987.jpg" alt=""></p><p>内置的支持多种调试方式，如：性能监控、元素检查等等</p><h3 id="logbox" tabindex="-1">LogBox <a class="header-anchor" href="#logbox" aria-label="Permalink to &quot;LogBox&quot;">​</a></h3><p>LogBox是一个应用内工具，当你的应用记录了警告或错误时，它会显示出来。类似于现在Web开发中一些工具，如：vite错误提示、webpack错误提示插件等等</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/debugging-logbox-076-d40ccb710b931f71132ca602b935c0a5.jpg" alt=""></p><p>当出现不可恢复的错误（例如JavaScript语法错误）时，LogBox将打开并显示错误的位置。在这种状态下，LogBox是不可解散的，因为您的代码无法执行。一旦语法错误通过快速刷新或手动重新加载修复，LogBox将自动消失</p><h3 id="性能监控" tabindex="-1">性能监控 <a class="header-anchor" href="#性能监控" aria-label="Permalink to &quot;性能监控&quot;">​</a></h3><p>在Android和iOS上，可以通过在开发菜单中选择“性能监视器”来切换应用程序内的性能覆盖</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-18_20.07.23.png" alt=""></p><blockquote><p>注意：性能监视器运行在应用程序内，是一个简单指标。建议研究Android Studio和Xcode下的本地工具，以获得准确的性能测量</p></blockquote><h3 id="terminal-log" tabindex="-1">Terminal Log <a class="header-anchor" href="#terminal-log" aria-label="Permalink to &quot;Terminal Log&quot;">​</a></h3><p>代码中所有的Log都会在控制台中同步打印</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-18_21.50.05.png" alt=""></p><h2 id="react-native-devtool" tabindex="-1">React Native DevTool <a class="header-anchor" href="#react-native-devtool" aria-label="Permalink to &quot;React Native DevTool&quot;">​</a></h2><p>在开发时运行App后，终端会展示很多快捷方式信息，其中有一条<code>open debugger</code>很明显</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-18_20.17.15.png" alt=""></p><p>我们直接按照提示按<code>j</code>键就可以打开<code>React Native DevTool</code>了 <img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/debugging-rndt-welcome-ac9602807bddf2752fc2a73c57028122.jpg" alt=""></p><h3 id="组件调试" tabindex="-1">组件调试 <a class="header-anchor" href="#组件调试" aria-label="Permalink to &quot;组件调试&quot;">​</a></h3><p>如果你开发ReactWeb应用程序应该会用到React Development Tool调试插件，此插件同样对ReactNative生效。如果你已经安装了，此时应该会看到<code>Components</code> tab 面板</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-18_20.30.32.png" alt=""></p><h3 id="log" tabindex="-1">Log <a class="header-anchor" href="#log" aria-label="Permalink to &quot;Log&quot;">​</a></h3><p>ReactNative DevTool和Chrome DevTool基本没啥区别，比如在源码中我们使用<code>log</code>打印信息</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">export</span><span style="color:#89DDFF;font-style:italic;"> default</span><span style="color:#C792EA;"> function</span><span style="color:#82AAFF;"> SettingsPage</span><span style="color:#89DDFF;">()</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#BABED8;">  console</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">log</span><span style="color:#F07178;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">settings...</span><span style="color:#89DDFF;">&quot;</span><span style="color:#F07178;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  return</span><span style="color:#89DDFF;"> &lt;</span><span style="color:#F07178;">h1</span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">Setting Page</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">h1</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>当打开<code>Setting</code>页面时可以在DevTool控制台中看到对应的log信息</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-18_20.21.26.png" alt=""></p><h3 id="源码调试" tabindex="-1">源码调试 <a class="header-anchor" href="#源码调试" aria-label="Permalink to &quot;源码调试&quot;">​</a></h3><p>在DevTool顶部中点击<code>Source</code>面板可以看到ReactNative项目对应的源码映射文件，你只需要在对应的文件中打断点即可</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-18_20.25.02.png" alt=""></p><p>同样的可以看到在进入<code>Setting</code>页面时就会自动卡在断点那里了</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-18_20.25.25.png" alt=""></p><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><p>初次之外还有几种其他的调试方式，由于它是基于Chrome DevTool实现的，所以在Chrome中的调试功能它基本上都有，在上方面板中可以看到：<code>Network</code>、<code>Memory</code>、<code>Profiler</code></p><h2 id="debug-native-ide" tabindex="-1">Debug Native IDE <a class="header-anchor" href="#debug-native-ide" aria-label="Permalink to &quot;Debug Native IDE&quot;">​</a></h2><p>当使用本地代码时，例如编写本地模块时，您可以从Android Studio或Xcode启动应用程序，并利用本地调试功能（设置断点等），就像构建标准的本地应用程序一样</p><p>另一种选择是使用React native CLI运行应用程序，并将本地IDE （Android Studio或Xcode）的本地调试器附加到该过程中</p><h3 id="xcode" tabindex="-1">Xcode <a class="header-anchor" href="#xcode" aria-label="Permalink to &quot;Xcode&quot;">​</a></h3><p>在Xcode上点击顶部菜单栏的“Debug”，选择“Attach to process”选项，在“Likely Targets”列表中选择该应用程序</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-18_22.06.17.png" alt=""></p><h3 id="android-studio" tabindex="-1">Android Studio <a class="header-anchor" href="#android-studio" aria-label="Permalink to &quot;Android Studio&quot;">​</a></h3><p>在Android Studio上，你可以通过打开菜单栏上的“Run”选项，点击<code>Attach to Process</code>并选择正在运行的React Native应用程序来做到这一点</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-18_22.07.04.png" alt=""></p><h2 id="真机调试" tabindex="-1">真机调试 <a class="header-anchor" href="#真机调试" aria-label="Permalink to &quot;真机调试&quot;">​</a></h2><p>默认在Expo的加持下真机调试变得更加简单，选择需要测试的真机，直接扫描终端中的二维码在手机设备中打开即可。默认会执行以下步骤：</p><ul><li>如果没有Expo App，手机将会安装Expo</li><li>拉取当前的App</li><li>真机将会自动启动App</li></ul><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-18_21.57.45.png" alt=""></p><p>这样就可以调试了</p><p>这里本人使用iPhone打开App</p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/IMG_0030.png" width="200"><p>接着可以继续通过DevTool或者相关快捷方式进行调试</p>`,55)),o(n),o(i)])}const _=l(h,[["render",g]]);export{f as __pageData,_ as default};
